import { parse } from "acorn";
export function jsToTreeNode(jsString, acornOpts = {
	ecmaVersion: "latest",
	sourceType: "module"
}) {
	return {
		type: "mdxjsEsm",
		value: "",
		data: { 
		// @ts-expect-error `parse` return types is incompatible but it should work in runtime
estree: {
			...parse(jsString, acornOpts),
			type: "Program",
			sourceType: "module"
		} }
	};
}
/**
* The MDX compiler cannot resolve string-form plugins the way the `.md` pipeline can,
* so drop them (with a warning) instead of letting the compiler throw.
*/
export function filterStringPlugins(plugins) {
	const validPlugins = [];
	let hasInvalidPlugin = false;
	for (const plugin of plugins) {
		if (typeof plugin === "string") {
			console.warn(`[@astrojs/mdx] \`${plugin}\` not applied.`);
			hasInvalidPlugin = true;
		} else if (Array.isArray(plugin) && typeof plugin[0] === "string") {
			console.warn(`[@astrojs/mdx] \`${plugin[0]}\` not applied.`);
			hasInvalidPlugin = true;
		} else {
			validPlugins.push(plugin);
		}
	}
	if (hasInvalidPlugin) {
		console.warn(`[@astrojs/mdx] To inherit Markdown plugins in MDX, use explicit imports in your config instead of "strings." See https://docs.astro.build/en/guides/markdown-content/#markdown-processor-plugins`);
	}
	return validPlugins;
}
